def sig(report):return {(e['source_id'],e['relative_path']):{k:v for k,v in e.items() if k!='observed_stat_at'} for e in report['entries']}
first=observe();second=observe();stable=sig(first)==sig(second) and first['directories']==second['directories'] and not first['errors'] and not second['errors']
if not stable:raise SystemExit('Observed inventory changed between passes or an enumeration error occurred; no immutable cutoff written. Retry with actual later time; never retrodate.')
