missing=[{'ledger_file_key':k,'source_id':v.get('source_id','incoming'),'relative_filename':v.get('relative_filename',k),'last_known_canonical_group_id':mod.canonical_group(ledger,v['group_id'])} for k,v in ledger['files'].items() if v.get('exists') and k not in presentkeys]
