print(json.dumps({'directory':str(O),'cutoff_at':cutoff,'manifest_sha256':sha(O/'cutoff-snapshot-manifest.json'),'inventory_sha256':sha(O/'file-inventory.json'),'counts':counts,'new_files':[e['relative_path'] for e in new],'nested_documents':[e['relative_path'] for e in nested]},ensure_ascii=False))
